   336	export function releaseProviderProcessSlot(
   337	  file: string | null,
   338	  token: string | null,
   339	  lockTiming: ProviderRegistryLockTiming = {},
   340	  mutationOps: ProviderRegistryMutationOps = DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS,
   341	): void {
   342	  if (!file || !token) return;
   343	  const dir = dirname(file);
   344	  withProviderRegistryLock(dir, () => {
   345	    const occupant = readSlotOccupant(file);
   346	    if (occupant.state !== 'valid' || occupant.token !== token) return;
   347	    mutationOps.unlink(file);
   348	  }, lockTiming);
   349	}
