   363	  if (!file || !token) return false;
   364	  if (
   365	    !Number.isInteger(identity.pid) || identity.pid <= 0
   366	    || !identity.processGroupIsolated
   367	    || !Number.isInteger(identity.pgid) || (identity.pgid ?? 0) <= 0
   368	  ) return false;
   369	  const dir = dirname(file);
   370	  return withProviderRegistryLock(dir, () => {
   371	    const occupant = readSlotOccupant(file);
   372	    if (occupant.state !== 'valid' || occupant.token !== token) return false;
   373	    const next: ProviderProcessSlotFileMeta = {
   374	      ...(occupant.meta as unknown as ProviderProcessSlotFileMeta),
   375	      pid: identity.pid,
   376	      providerPid: identity.pid,
   377	      providerPgid: identity.pgid!,
   378	      providerSpawnedAt: identity.spawnedAt,
   379	      providerStartFingerprint: identity.startFingerprint ?? undefined,
   380	      providerProcessGroupIsolated: true,
   381	      token,
   382	    };
   383	    const temporary = `${file}.${token}.transfer`;
   384	    writeFileSync(temporary, JSON.stringify(next), { encoding: 'utf8', flag: 'wx', mode: 0o600 });
   385	    try {
   386	      // Registry lock + exact token check makes this replacement ownership-safe.
   387	      renameSync(temporary, file);
   388	    } finally {
   389	      try { unlinkSync(temporary); } catch { /* rename already consumed it */ }
   390	    }
   160	      subjectMatches: false,
   161	      storyMatches: false,
   162	      gatePhaseMatches: true,
   163	      producerBoundaryTrusted: false,
   164	    },
   165	  });
   166	}
